messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Low-Poly Treadmill Walk/Run</title>
    <style>
        html, body { margin: 0; padding: 0; overflow: hidden; background: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202430);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.2, 100);
camera.position.set(0, 2.2, 7.5);
camera.lookAt(0, 1, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.5);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(5, 8, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 1024;
dirLight.shadow.mapSize.height = 1024;
dirLight.shadow.camera.top = 5;
dirLight.shadow.camera.bottom = -5;
dirLight.shadow.camera.left = -5;
dirLight.shadow.camera.right = 5;
scene.add(dirLight);

// Treadmill-style ground
const groundGeo = new THREE.PlaneGeometry(10, 100);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3a3a, roughness: 0.7, metalness: 0.1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.z = -45;
ground.receiveShadow = true;
scene.add(ground);

// Treadmill belt texture (simple repeating pattern)
function createBeltTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');
    // Dark base
    ctx.fillStyle = '#2a2a2a';
    ctx.fillRect(0, 0, 256, 64);
    // Stripes
    ctx.fillStyle = '#383838';
    for (let i = 0; i < 256; i += 16) {
        ctx.fillRect(i, 0, 12, 64);
    }
    // Top border
    ctx.fillStyle = '#404040';
    ctx.fillRect(0, 0, 256, 2);
    return new THREE.CanvasTexture(canvas);
}

const beltMat = new THREE.MeshStandardMaterial({ map: createBeltTexture(), roughness: 0.8, metalness: 0.1 });
const beltGeo = new THREE.PlaneGeometry(1, 100);
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.rotation.x = -Math.PI / 2;
belt.position.z = -45;
belt.position.y = 0.02; // just above ground
belt.receiveShadow = true;
scene.add(belt);

// Treadmill frame (legs)
const legGeo = new THREE.BoxGeometry(0.15, 5, 0.15);
const legMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5 });
const legL = new THREE.Mesh(legGeo, legMat);
const legR = new THREE.Mesh(legGeo, legMat);
legL.position.set(-2.2, -2.5, 0);
legR.position.set(2.2, -2.5, 0);
legL.castShadow = true; legR.castShadow = true;
scene.add(legL, legR);

// Humanoid group
const humanoid = new THREE.Group();
scene.add(humanoid);

// Materials
const skinMat = new THREE.MeshStandardMaterial({ color: 0xffd8a8, roughness: 0.4 });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3b82f6, roughness: 0.3 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x111827, roughness: 0.6 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x1f2937, roughness: 0.5 });

// Simple low-poly torso
const torsoGeo = new THREE.BoxGeometry(0.8, 1.0, 0.35);
const torso = new THREE.Mesh(torsoGeo, shirtMat);
torso.position.y = 1.4;
torso.castShadow = true;
humanoid.add(torso);

// Head
const headGeo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
const head = new THREE.Mesh(headGeo, skinMat);
head.position.y = 2.1;
head.castShadow = true;
humanoid.add(head);

// Arms (upper and lower for swing)
function createArm() {
    const group = new THREE.Group();
    const upperGeo = new THREE.BoxGeometry(0.18, 0.55, 0.18);
    const upper = new THREE.Mesh(upperGeo, skinMat);
    upper.position.y = 0.275;
    upper.castShadow = true;
    const lowerGeo = new THREE.BoxGeometry(0.15, 0.55, 0.15);
    const lower = new THREE.Mesh(lowerGeo, skinMat);
    lower.position.y = -0.275;
    lower.castShadow = true;
    group.add(upper, lower);
    return group;
}
const armL = createArm();
const armR = createArm();
armL.position.set(-0.55, 1.4, 0);
armR.position.set(0.55, 1.4, 0);
humanoid.add(armL, armR);

// Legs (upper and lower)
function createLeg() {
    const group = new THREE.Group();
    const upperGeo = new THREE.BoxGeometry(0.22, 0.65, 0.22);
    const upper = new THREE.Mesh(upperGeo, pantsMat);
    upper.position.y = 0.325;
    upper.castShadow = true;
    const lowerGeo = new THREE.BoxGeometry(0.18, 0.65, 0.18);
    const lower = new THREE.Mesh(lowerGeo, shoeMat);
    lower.position.y = -0.325;
    lower.castShadow = true;
    group.add(upper, lower);
    return group;
}
const legL = createLeg();
const legR = createLeg();
legL.position.set(-0.35, 1.0, 0);
legR.position.set(0.35, 1.0, 0);
humanoid.add(legL, legR);

// State variables
let time = 0;
let phase = 'stand'; // stand, walk, run
let beltOffset = 0;
let beltSpeed = 0;

// Parameters
const standDuration = 2000;
const walkDuration = 3000;
const runDuration = 3000;
const cycleDuration = standDuration + walkDuration + runDuration;

// Animation helpers
function resetLimbs() {
    torso.rotation.set(0, 0, 0);
    armL.rotation.set(0, 0, 0);
    armR.rotation.set(0, 0, 0);
    legL.rotation.set(0, 0, 0);
    legR.rotation.set(0, 0, 0);
    beltOffset = 0;
}

function walk(t) {
    // t in [0,1]
    // Arms: swing opposite to legs, moderate amplitude
    const armSwing = Math.sin(t * Math.PI * 2) * 0.25;
    armL.rotation.z = armSwing;
    armR.rotation.z = -armSwing;

    // Legs: opposite swing, moderate amplitude
    const legSwing = Math.sin(t * Math.PI * 2) * 0.18;
    legL.rotation.z = legSwing;
    legR.rotation.z = -legSwing;

    // Slight torso sway
    torso.rotation.x = Math.sin(t * Math.PI * 2) * 0.02;

    // Belt moves forward at walking pace
    beltSpeed = 0.12;
    beltOffset += beltSpeed;
}

function run(t) {
    // t in [0,1]
    // Arms: faster, larger swing, slight forward lean
    const armSwing = Math.sin(t * Math.PI * 2) * 0.45;
    armL.rotation.z = armSwing;
    armR.rotation.z = -armSwing;

    // Legs: higher cadence, larger swing, slight knee bend via Y rotation
    const legSwing = Math.sin(t * Math.PI * 2) * 0.30;
    legL.rotation.z = legSwing;
    legR.rotation.z = -legSwing;
    legL.rotation.x = Math.sin(t * Math.PI * 2) * -0.05;
    legR.rotation.x = Math.sin(t * Math.PI * 2) * -0.05;

    // Torso lean forward slightly
    torso.rotation.x = Math.sin(t * Math.PI * 2) * 0.04 + 0.08;

    // Belt moves faster
    beltSpeed = 0.22;
    beltOffset += beltSpeed;
}

function stand() {
    beltSpeed = 0;
    beltOffset = 0;
    // Reset limbs to neutral
    armL.rotation.set(0, 0, 0);
    armR.rotation.set(0, 0, 0);
    legL.rotation.set(0, 0, 0);
    legR.rotation.set(0, 0, 0);
    torso.rotation.set(0, 0, 0);
}

// Animation loop
let lastTime = performance.now();

function animate(now) {
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;

    time += dt;

    // Phase management
    if (phase === 'stand') {
        if (time >= standDuration / 1000) {
            phase = 'walk';
            time = 0;
        }
        stand();
    } else if (phase === 'walk') {
        const t = time / (walkDuration / 1000);
        if (t >= 1) {
            phase = 'run';
            time = 0;
        }
        walk(t);
    } else if (phase === 'run') {
        const t = time / (runDuration / 1000);
        if (t >= 1) {
            phase = 'stand';
            time = 0;
        }
        run(t);
    }

    // Belt texture offset
    const beltTex = beltMat.map;
    if (beltTex) {
        beltTex.offset.y = (beltOffset % 1) * -beltTex.repeat.y;
    }

    // Simple bobbing for walking/running
    if (phase === 'walk') {
        humanoid.position.y = Math.sin(time * Math.PI * 2) * 0.015;
    } else if (phase === 'run') {
        humanoid.position.y = Math.sin(time * Math.PI * 2) * 0.03;
    }

    renderer.render(scene, camera);
    requestAnimationFrame(animate);
}

// Start immediately
lastTime = performance.now();
animate(lastTime);

// Handle resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
